package com.lyrashop.audit.web;import java.util.Set;import java.util.UUID;import org.springframework.stereotype.Component;import com.lyrashop.audit.service.AdminAuditService;import jakarta.servlet.http.*;import org.springframework.web.servlet.HandlerInterceptor;@Component public class AdminAuditInterceptor implements HandlerInterceptor{private static final Set<String> WRITE=Set.of("POST","PUT","PATCH","DELETE");private final AdminAuditService audit;public AdminAuditInterceptor(AdminAuditService audit){this.audit=audit;}@Override public void afterCompletion(HttpServletRequest request,HttpServletResponse response,Object handler,Exception exception){if(!request.getRequestURI().startsWith("/api/v1/admin/")||!WRITE.contains(request.getMethod())||response.getStatus()>=400||request.getUserPrincipal()==null)return;try{audit.record(UUID.fromString(request.getUserPrincipal().getName()),request.getMethod(),request.getRequestURI(),response.getStatus(),request.getRemoteAddr(),request.getHeader("User-Agent"));}catch(RuntimeException ignored){}}}
